43	bool PreparedStatementData::RequireRebind(ClientContext &context,
44	                                          optional_ptr<case_insensitive_map_t<BoundParameterData>> values) {
45		idx_t count = values ? values->size() : 0;
46		CheckParameterCount(count);
47		if (!unbound_statement) {
48			throw InternalException("Prepared statement without unbound statement");
49		}
50		if (properties.always_require_rebind) {
51			// this statement must always be re-bound
52			return true;
53		}
54		if (!properties.bound_all_parameters) {
55			// parameters not yet bound: query always requires a rebind
56			return true;
57		}
58		for (auto &it : value_map) {
59			auto &identifier = it.first;
60			auto lookup = values->find(identifier);
61			if (lookup == values->end()) {
62				break;
63			}
64			if (lookup->second.GetValue().type() != it.second->return_type) {
65				return true;
66			}
67		}
68		// Check the catalog versions to ensure all catalog entries we rely on are current
69		for (auto &it : properties.read_databases) {
70			if (!CheckCatalogIdentity(context, it.first, it.second)) {
71				return true;
72			}
73		}
74		for (auto &it : properties.modified_databases) {
75			if (!CheckCatalogIdentity(context, it.first, it.second)) {
76				return true;
77			}
78		}
79		return false;
80	}
