82	void PreparedStatementData::Bind(case_insensitive_map_t<BoundParameterData> values) {
83		// set parameters
84		D_ASSERT(!unbound_statement || unbound_statement->named_param_map.size() == properties.parameter_count);
85		CheckParameterCount(values.size());
86	
87		// bind the required values
88		for (auto &it : value_map) {
89			const string &identifier = it.first;
90			auto lookup = values.find(identifier);
91			if (lookup == values.end()) {
92				throw BinderException("Could not find parameter with identifier %s", identifier);
93			}
94			D_ASSERT(it.second);
95			auto value = lookup->second.GetValue();
96			if (!value.DefaultTryCastAs(it.second->return_type)) {
97				throw BinderException(
98				    "Type mismatch for binding parameter with identifier %s, expected type %s but got type %s", identifier,
99				    it.second->return_type.ToString().c_str(), value.type().ToString().c_str());
100			}
101			it.second->SetValue(std::move(value));
102		}
103	}
